```typescript
export interface ChromeParts {
  top: readonly string[];
  bottom: readonly string[];
}

export interface DocumentView {
  top: string[];
  body: string[];
  bottom: string[];
  regions: readonly [string[], string[], string[]];
}

export function composeDocument(chrome: ChromeParts, body: readonly string[]): DocumentView {
  if (typeof chrome !== "object" || chrome === null || Array.isArray(chrome) ||
      !Array.isArray(chrome.top) || !Array.isArray(chrome.bottom) || !Array.isArray(body) ||
      !chrome.top.every(value => typeof value === "string") ||
      !chrome.bottom.every(value => typeof value === "string") ||
      !body.every(value => typeof value === "string")) {
    throw new TypeError("invalid document parts");
  }
  const top = Array.from(chrome.top);
  const content = Array.from(body);
  const bottom = Array.from(chrome.bottom);
  return { top, body: content, bottom, regions: [top, bottom, content] };
}
```

