import { composeDocument } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function arrayEqual(actual: readonly string[], expected: readonly string[], message: string): void {
  equal(JSON.stringify(actual), JSON.stringify(expected), message);
}
function throwsTypeError(action: () => unknown, message: string): void {
  try { action(); } catch (error) { if (error instanceof TypeError) return; throw new Error(`${message}: expected TypeError`); }
  throw new Error(`${message}: expected throw`);
}

const top = ['header', 'nav'];
const bottom = ['footer'];
const body = ['first', '', 'third'];
const view = composeDocument({ top, bottom }, body);
arrayEqual(view.top, ['header', 'nav'], 'top copied in order');
arrayEqual(view.body, ['first', '', 'third'], 'body retains order and empty strings');
arrayEqual(view.bottom, ['footer'], 'bottom copied');
assert(view.regions[0] === view.top, 'first region is exact result-owned top array');
assert(view.regions[1] === view.body, 'second region is exact result-owned body array');
assert(view.regions[2] === view.bottom, 'third region is exact result-owned bottom array');
assert(view.top !== top, 'top does not alias input');
assert(view.body !== body, 'body does not alias input');
assert(view.bottom !== bottom, 'bottom does not alias input');

top[0] = 'changed';
top.push('added');
body.length = 0;
bottom[0] = 'changed';
arrayEqual(view.top, ['header', 'nav'], 'later top mutation is isolated');
arrayEqual(view.body, ['first', '', 'third'], 'later body mutation is isolated');
arrayEqual(view.bottom, ['footer'], 'later bottom mutation is isolated');

const sourceChrome = { top: ['x'], bottom: ['y'] };
const firstCall = composeDocument(sourceChrome, ['z']);
const secondCall = composeDocument(sourceChrome, ['z']);
assert(firstCall.top !== secondCall.top, 'separate calls do not share top arrays');
assert(firstCall.body !== secondCall.body, 'separate calls do not share body arrays');
assert(firstCall.bottom !== secondCall.bottom, 'separate calls do not share bottom arrays');
firstCall.top.push('mutation');
arrayEqual(secondCall.top, ['x'], 'separate call state is independent');

const empty = composeDocument({ top: [], bottom: [] }, []);
arrayEqual(empty.top, [], 'empty top valid');
arrayEqual(empty.body, [], 'empty body valid');
arrayEqual(empty.bottom, [], 'empty bottom valid');
assert(empty.regions[0] === empty.top && empty.regions[1] === empty.body && empty.regions[2] === empty.bottom, 'empty region references are exact');

const malformedChrome: unknown[] = [null, [], 'chrome', {}, { top: [], bottom: null }, { top: 'x', bottom: [] }, { top: [1], bottom: [] }, { top: [], bottom: [false] }];
for (const chrome of malformedChrome) {
  throwsTypeError(() => composeDocument(chrome as Parameters<typeof composeDocument>[0], []), 'malformed chrome');
}
for (const malformedBody of [null, {}, 'body', ['ok', 1]]) {
  throwsTypeError(() => composeDocument({ top: [], bottom: [] }, malformedBody as unknown as readonly string[]), 'malformed body');
}

